<?php
function handleAuth(string $path):never {
 $method=$_SERVER['REQUEST_METHOD'];if($path==='status'&&$method==='GET'){$s=sessionRow();out(['loggedIn'=>(bool)$s,'csrf'=>$s['csrf']??null,'setupRequired'=>!row('SELECT 1 FROM system_state WHERE key=?',['owner_initialized'])]);}
 if($method!=='POST')fail('Método não permitido.',405);$b=body();$ip=$_SERVER['REMOTE_ADDR']??'unknown';
 if($path==='logout'){$s=auth();csrf($s);q('DELETE FROM sessions WHERE token_hash=?',[$s['token_hash']]);setcookie(cookieName(),'', ['expires'=>time()-3600,'path'=>'/','secure'=>getenv('APP_ENV')!=='test','httponly'=>true,'samesite'=>'Lax']);out(['ok'=>true]);}
 if($path==='password'){$s=auth();csrf($s);rate('password:'.$s['user_id'],5);$u=row('SELECT * FROM users WHERE id=?',[$s['user_id']]);if(!password_verify((string)($b['current']??''),$u['password_hash']))fail('Senha atual incorreta.');$password=(string)($b['password']??'');if(strlen($password)<12||strlen($password)>128)fail('Use uma senha de 12 a 128 caracteres.');transaction(function()use($password,$s){q('UPDATE users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_ARGON2ID),$s['user_id']]);q('DELETE FROM sessions WHERE user_id=?',[$s['user_id']]);});out(sessionCreate($s['user_id']));}
 if(!in_array($path,['register','login','setup','recover'],true))fail('Rota não encontrada.',404);
 $email=strtolower(clean($b['email']??'',254));$password=(string)($b['password']??'');rate('auth-ip:'.$ip,40);rate('auth-email:'.$email,10);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)>128)fail('E-mail ou senha inválidos.');
 if($path==='recover'){$u=row('SELECT * FROM users WHERE email=?',[$email]);if(!$u||!hash_equals($u['recovery_hash'],hash('sha256',(string)($b['recovery']??''))))fail('E-mail ou código de recuperação inválido.',401);if(strlen($password)<12)fail('Use uma senha de pelo menos 12 caracteres.');$recovery=bin2hex(random_bytes(24));transaction(function()use($u,$password,$recovery){q('UPDATE users SET password_hash=?,recovery_hash=? WHERE id=?',[password_hash($password,PASSWORD_ARGON2ID),hash('sha256',$recovery),$u['id']]);q('DELETE FROM sessions WHERE user_id=?',[$u['id']]);});out(array_merge(sessionCreate($u['id']),['recoveryCode'=>$recovery]));}
 if($path==='login'){$u=row('SELECT * FROM users WHERE email=?',[$email]);$dummy='$2y$12$5RbGcy6h05eFpEFX/JJGPu7plrsTNQdqXscWWPfA.jb6HCGIjXnBi';if(!password_verify($password,$u['password_hash']??$dummy))fail('E-mail ou senha incorretos.',401);if(password_needs_rehash($u['password_hash'],PASSWORD_ARGON2ID))q('UPDATE users SET password_hash=? WHERE id=?',[password_hash($password,PASSWORD_ARGON2ID),$u['id']]);out(sessionCreate($u['id']));}
 if(strlen($password)<12)fail('Use uma senha de pelo menos 12 caracteres.');$name=clean($b['name']??'');$phone=phone($b['phone']??'');if(strlen($name)<2||strlen($phone)<10||strlen($phone)>15)fail('Informe nome e telefone com DDD.');$user=id();$recovery=bin2hex(random_bytes(24));
 if($path==='setup'){$secret=getenv('ADMIN_SETUP_TOKEN')?:'';if(strlen($secret)<32||!hash_equals($secret,(string)($b['token']??''))||$email!==strtolower(getenv('ADMIN_EMAIL')?:''))fail('Código de ativação inválido.',403);transaction(function()use($name,$phone,$email,$password,$recovery,&$user){if(row('SELECT 1 FROM system_state WHERE key=?',['owner_initialized']))fail('Administrador já ativado.',409);$existing=row('SELECT id FROM users WHERE email=?',[$email]);if($existing){$user=$existing['id'];q('UPDATE users SET name=?,phone=?,password_hash=?,recovery_hash=? WHERE id=?',[$name,$phone,password_hash($password,PASSWORD_ARGON2ID),hash('sha256',$recovery),$user]);q('DELETE FROM sessions WHERE user_id=?',[$user]);}else q('INSERT INTO users VALUES(?,?,?,?,?,?,?)',[$user,$email,$name,$phone,password_hash($password,PASSWORD_ARGON2ID),hash('sha256',$recovery),time()]);q('INSERT INTO shops(id,name,owner,phone) VALUES(?,?,?,?)',['alan-barber','Alan Barber',$user,'5551999938323']);q('INSERT INTO members VALUES(?,?,?)',['alan-barber',$user,'admin']);$services=[['Corte masculino',40,5000],['Barba',30,4000],['Corte + barba',70,8000],['Sobrancelha',15,2500],['Degradê',45,5500]];foreach($services as $i=>$v)q('INSERT INTO services VALUES(?,?,?,?,?,1)',['alan-service-'.$i,'alan-barber',...$v]);foreach(['Alan Souza','Lucas Pereira','Rafael Lima'] as $i=>$name)q('INSERT INTO staff VALUES(?,?,?,1)',['alan-staff-'.$i,'alan-barber',$name]);q('INSERT INTO system_state VALUES(?,?)',['owner_initialized',$user]);});}
 else {if(row('SELECT id FROM users WHERE email=?',[$email]))fail('Não foi possível cadastrar este e-mail. Entre na sua conta ou fale com a barbearia.',409);q('INSERT INTO users VALUES(?,?,?,?,?,?,?)',[$user,$email,$name,$phone,password_hash($password,PASSWORD_ARGON2ID),hash('sha256',$recovery),time()]);}
 out(array_merge(sessionCreate($user),['recoveryCode'=>$recovery]),201);
}
